import 'package:eduflow_core/eduflow_core.dart';
import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import 'package:go_router/go_router.dart';

final parentProfileProvider = FutureProvider<Map<String, dynamic>>((ref) async { final r = await ref.watch(dioClientProvider).dio.get('/parent/profile'); return Map<String, dynamic>.from((r.data as Map)['data'] as Map); });
class ParentLeaveScreen extends ConsumerStatefulWidget { const ParentLeaveScreen({super.key}); @override ConsumerState<ParentLeaveScreen> createState() => _ParentLeaveScreenState(); }
class _ParentLeaveScreenState extends ConsumerState<ParentLeaveScreen> { int? studentId; DateTime? start; DateTime? end; final reason = TextEditingController(); bool saving = false; @override void dispose(){reason.dispose();super.dispose();} String date(DateTime? d)=>d==null?'Select date':'${d.year}-${d.month.toString().padLeft(2,'0')}-${d.day.toString().padLeft(2,'0')}'; Future<void> pick(bool isStart) async { final d=await showDatePicker(context:context,initialDate:isStart?(start??DateTime.now()):(end??start??DateTime.now()),firstDate:DateTime.now().subtract(const Duration(days:1)),lastDate:DateTime.now().add(const Duration(days:730))); if(d!=null)setState(()=>isStart?start=d:end=d); } Future<void> submit() async {if(studentId==null||start==null||end==null||reason.text.trim().isEmpty)return;setState(()=>saving=true);try{await ref.read(dioClientProvider).dio.post('/parent/leaves',data:{'student_id':studentId,'start_date':date(start),'end_date':date(end),'reason':reason.text.trim()});if(mounted){ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Leave request sent to Management.')));context.pop();}}finally{if(mounted)setState(()=>saving=false);}} @override Widget build(BuildContext context){final state=ref.watch(parentProfileProvider);return Scaffold(appBar:AppBar(title:const Text('Student leave'),leading:IconButton(onPressed:()=>context.go('/parent'),icon:const Icon(Icons.arrow_back_rounded))),body:state.when(loading:()=>const Center(child:CircularProgressIndicator()),error:(e,_)=>const Center(child:Text('Could not load linked children.')),data:(profile){final students=((profile['students'] as List?)??const[]).whereType<Map>().map((x)=>Map<String,dynamic>.from(x)).toList();return ListView(padding:const EdgeInsets.all(16),children:[const Text('Request leave',style:TextStyle(fontSize:24,fontWeight:FontWeight.w800)),const SizedBox(height:16),DropdownButtonFormField<int>(value:studentId,decoration:const InputDecoration(labelText:'Child'),items:students.map((s)=>DropdownMenuItem(value:s['id'] as int?,child:Text('${s['name']} · ${s['roll_number']}'))).where((x)=>x.value!=null).cast<DropdownMenuItem<int>>().toList(),onChanged:(v)=>setState(()=>studentId=v)),const SizedBox(height:12),Row(children:[Expanded(child:OutlinedButton(onPressed:()=>pick(true),child:Text('From: ${date(start)}'))),const SizedBox(width:8),Expanded(child:OutlinedButton(onPressed:()=>pick(false),child:Text('To: ${date(end)}')))]),const SizedBox(height:12),TextField(controller:reason,maxLines:4,decoration:const InputDecoration(labelText:'Reason')),const SizedBox(height:18),SizedBox(width:double.infinity,child:FilledButton(onPressed:saving?null:submit,child:Text(saving?'Sending…':'Submit request')))]);})) ;}}
